import json, re
cfg = json.loads(read('renovate.json'))
src = read('versions.toml')
def py_rx(p):
    return re.compile(p.replace('(?<', '(?P<'))
for m in cfg['regexManagers']:
    for ms in m['matchStrings']:
        rx = py_rx(ms)
        hits = 0
        for line in src.splitlines():
            mt = rx.search(line)
            if mt and 'currentValue' in mt.groupdict():
                hits += 1
                ex = re.compile(m['extractVersion'].replace('(?<','(?P<')).match(mt['currentValue'])
                print(f"{ms!r}")
                print(f"  line: {line.strip()}")
                print(f"  currentValue={mt['currentValue']!r} -> dep {m['depNameTemplate']} ({m['datasourceTemplate']})")
                print(f"  extractVersion: {ex.group('version') if ex else '(no match -> used as-is)'}  versioning={m['versioningTemplate']}")
        print(f"  hits: {hits}\n")

